      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n총소요시간 2시간 15만원) 9월 28일~10월 4일 까지) 5세미만 유자녀 30세~35세 엄마) 돌봄 관련 온라인 커뮤니티 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.17. 16:03\n조회 75\n구독\n총소요시간 2시간 15만원) 9월 28일~10월 4일 까지) 5세미만 유자녀 30세~35세 엄마) 돌봄 관련 온라인 커뮤니티 조사\n총소요시간 2시간 15만원) 9월 28일~10월 4일 까지) 5세미만 유자녀 25세~35세 엄마) 돌봄 관련 온라인 커뮤니티 조사\n신청하신분은 재신청 안하셔도 됩니다\n참여과제는 : 9월 28일 ~10월 4일 까지\n온라인 플랫폼 : 총 8~10개의 과제를 제출하여야 함/ 총소요시간 2시간\n사례비 : 15만원\n(하나당 1~2분 길이 , 처음에 영상 7개 제출후 추가로 2~3개 제출 함 )\n연구 목적: 돌봄에 관하여 사람들의 실제 삶에서 벌어지는 일들을 가까이서 살펴봄\n진행 방식: 일주일 동안 가족 , 주거환경, 대인관계, 건강상태및 일상적인 돌봄 루틴을 공유함\n영상 촬영을 잘 하고, 거부감이 없는 사람 (본인과 가족촬영, 가족 촬영은 필수가 아님 )\n카메라 앞에서 자신의 감정을 편안하게 표현 할수 있는 사람 , 기쁨 슬픔 감정적인 반응을 이끌어 낼수 있는 다큐스타일의영상이 이상적\n아파트 또는 타운 하우스 거주 , 뷰티와 웰빙에 관심이 많은 사람\n타인에 돌봄을 받아 들이는데 해당 하는것 ? 번호로 적어 주세요.\n1. 혼자 해결하는 것을 선호한다, 남의 도움을 받으면 불편하고 주도권을 잃은듯한 기분이다\n2. 타인에게 의존하는 것을 좋아 하지 않지만, 도움을 주는 사람이 있다면 받아 들인다.\n3. 도움을 주고받는 것에 익숙하다, 모든 걸 혼자서 할 수는 없다.\n적어주실 내용: (여자)이름 /생년월일 / 엄마나이 / 자녀나이/ 거주지역 /, 거주형태 /아파트여야 함 타운하우스나 평형/ 소득/ 배우자 직업\nhttps://forms.gle/r2pSmDSbETSxzQe7A\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.17. 16:39 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n만나이 19~45세 여성 (2007~1980년생) 간식 맛 테스트 갱조사\n좌담회알바좌담회카페\n26.09.17.\n댓글\n1\n총소요시간 2시간 15만원) 9월 28일~10월 4일 까지) 5세미만 유자녀 30세~35세 엄마) 돌봄 관련 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.09.17.\n댓글\n1\n총소요시간 2시간 15만원) 9월 28일~10월 4일 까지) 5세미만 유자녀 25세~29세 엄마) 돌봄 관련 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.09.17.\n댓글\n1\n급급급) 총소요시간 2시간 15만원) 55세이상 남성) 9월 28일~10월 4일 까지) 손주 돌봄 관련 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.09.17.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
