      "location": "",
      "type": "좌담회",
      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10월 중) 수도권,부산,대구,대전,광주,제주까지 대상) 포르쉐 차주를 찾습니다\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.17. 17:36\n조회 15\n구독\n10월 중) 수도권,부산,대구,대전,광주,제주까지 대상) 포르쉐 / 랜드로버 차주를 찾습니다\n10월 중 AS센터 방문 계획이 있는 차주님을 찾습니다.\n수도권, 부산, 대구, 대전, 광주, 제주까지 전국 대상이며,\n정비 계획이 있는 차주님이 예약 → 입고 → 정비 → 당일 출고하신 후 이용 만족도 조사를 응답하는 조사로, 아래 내용 확인하시어 신청 부탁드립니다 ^^\n■ 대상 서비스\n- 엔진오일 + 필터 교환\n- 에어컨 필터 교환\n- 와이퍼 블레이드 교환\n- 브레이크 오일 / 패드 교환\n- 점화플러그 또는 연료필터 교환\n- 그 외 무상 수리 혹은 당일 입고 및 출고 가능한 서비스\n■ 참여 조건\n- 차주가 방문 희망하는 날로 예약 후 방문일에 조사원을 만나 설명 듣고 입고 & 출고 후 설문조사 참여\n- 모든 과정 녹취 필수\n- 10월 중 입고 예정 있는 포르쉐 / 랜드로버 차주\n■ 참여 사례비\n- 서비스센터 방문 후 설문조사 참여 + 온라인 좌담회 참여(11월 중순 예정) :\n참여 종료 후 40만원 계좌지급\n후보자 명단은 방문 예정 서비스 항목, 해당 서비스센터, 성함과 전화번호를 전달해 주시면 순차 연락 드리겠습니다.\n많은 관심과 참여 부탁드립니다.\nhttps://forms.gle/UpkyMJKrzRfAsP1f8\n10월 중) 수도권,부산,대구,대전,광주,제주까지 대상) 포르쉐 / 랜드로버 차주를 찾습니다\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.17. 18:55 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n10월 중) 수도권,부산,대구,대전,광주,제주까지 대상)랜드로버 차주를 찾습니다\n좌담회알바좌담회카페\n26.09.17.\n댓글\n1\n10월 중) 수도권,부산,대구,대전,광주,제주까지 대상) 포르쉐 차주를 찾습니다\n좌담회알바좌담회카페\n26.09.17.\n댓글\n1\n10/1~2) 만 20-59세 남/여) 홈 프로젝터 좌담회\n좌담회알바좌담회카페\n26.09.17.\n댓글\n1\n만나이 19~45세 여성 (2007~1980년생) 간식 맛 테스트 갱조사\n좌담회알바좌담회카페\n26.09.17.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
